fields = {t['name']: [f['name'] for f in t['fields']] for t in schema['tables']}

bad = []
def check_span(span, where):
    if span is None:
        return
    if isinstance(span, list):
        for s in span:
            check_span(s, where)
        return
    if span not in paper:
        bad.append((where, span))

n = {}
for tname, rows in out['tables'].items():
    n[tname] = len(rows)
    for i, row in enumerate(rows):
        missing = [f for f in fields[tname] if f not in row]
        extra = [f for f in row if f not in fields[tname]]
        if missing or extra:
            bad.append((f'{tname}[{i}] fields', f'missing={missing} extra={extra}'))
        for f, cell in row.items():
            if not isinstance(cell, dict) or 'value' not in cell or 'span' not in cell:
                bad.append((f'{tname}[{i}].{f}', 'not a cell'))
                continue
            check_span(cell['span'], f'{tname}[{i}].{f}')

# checklist completeness
labels = [r['individual_label_in_paper']['value'] for r in out['tables']['individuals']]
feat = ["oral ulcers","genital ulcers","gastrointestinal ulcers or inflammation","recurrent fever","arthritis or arthralgia","uveitis or other ocular inflammation","skin lesions (rash, folliculitis, erythema nodosum)","autoimmune thyroiditis","type 1 diabetes","autoimmune hepatitis","cytopenia (autoimmune)","lymphoproliferation or lymphadenopathy","central nervous system involvement","recurrent infections","elevated inflammatory markers (CRP/ESR)","autoantibodies (ANA/other)","growth failure","pericarditis or other serositis","interstitial lung disease","vasculitis"]
seen = {}
for r in out['tables']['phenotype_checklist']:
    seen.setdefault(r['individual_label_in_paper']['value'], []).append(r['checklist_feature']['value'])
for l in labels:
    got = seen.get(l, [])
    if sorted(got) != sorted(feat):
        bad.append((f'checklist {l}', f'{len(got)} rows, missing {set(feat)-set(got)}'))

# labels consistent across tables
for t in ['variants','phenotypic_features','phenotype_checklist']:
    for i, r in enumerate(out['tables'][t]):
        if r['individual_label_in_paper']['value'] not in labels:
            bad.append((f'{t}[{i}] label', r['individual_label_in_paper']['value']))

# evidence_basis required where status != not reported
for t in ['phenotypic_features','phenotype_checklist']:
    for i, r in enumerate(out['tables'][t]):
        st = r['status']['value']
        eb = r['evidence_basis']['value']
        if st != 'not reported' and eb == 'not reported':
            bad.append((f'{t}[{i}] evidence_basis', 'missing'))
        if st == 'not reported' and eb != 'not reported':
            bad.append((f'{t}[{i}] evidence_basis', 'should be not reported'))

# empty cells inside cells: value None must pair with span None
for tname, rows in out['tables'].items():
    for i, row in enumerate(rows):
        for f, cell in row.items():
            if cell['value'] is None and cell['span'] is not None:
                bad.append((f'{tname}[{i}].{f}', 'null value with span'))
            if cell['value'] == 'not reported' and cell['span'] is not None:
                bad.append((f'{tname}[{i}].{f}', 'not reported with span'))

print('rows per table:', n)
print('individuals:', len(labels), labels)
print('reports_individuals_with_tnfaip3_variant:', out['reports_individuals_with_tnfaip3_variant'])
print('PROBLEMS:', len(bad))
for b in bad[:40]:
